import React, { useState, useEffect, useRef, useCallback, useMemo } from "react";
import { Waves, RotateCcw, Info, Trophy, Users, ChevronDown, ChevronUp, Play, X } from "lucide-react";

export const SAND_BACK = "data:image/jpeg;base64,";
export const TILE_CARAMEL = "data:image/png;base64,";
export const TILE_CHOCOLATE = "data:image/png;base64,";
export const TILE_SEASALT = "data:image/png;base64,";
export const TILE_TIDE = "data:image/png;base64,";


/* ============================================================
   CHOCOLATE SEA SALT CARAMELS — Playtest App (v5 ruleset)
   ============================================================ */

const TYPE_ICON = {
  salt: TILE_SEASALT,
  caramel: TILE_CARAMEL,
  chocolate: TILE_CHOCOLATE,
  tide: TILE_TIDE,
};

const TYPE_LABEL = { salt: "Sea Salt", caramel: "Caramel", chocolate: "Chocolate", tide: "Rising Tide" };

const TYPE_COLORS = {
  salt: { bg: "#EDF3F4", border: "#8FB3BE", text: "#2C4A54" },
  caramel: { bg: "#FBEBD9", border: "#D99A56", text: "#8C5525" },
  chocolate: { bg: "#E9DDD6", border: "#8A6656", text: "#3E2723" },
  tide: { bg: "#DCEEF2", border: "#4FA3BD", text: "#134A5C" },
};

const BOT_NAMES = ["Sandy", "Chip", "Marina", "Barnacle"];

function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function createTilePool() {
  // v5: each ingredient tile carries a chevron value (1, 2, or 3). Per
  // ingredient type: 6 tiles worth 1, 6 worth 2, 3 worth 3 (15 total).
  const ingredientTypes = ["salt", "caramel", "chocolate"];
  const valueCounts = [
    [1, 6],
    [2, 6],
    [3, 3],
  ];
  const tiles = [];
  let id = 0;
  for (const t of ingredientTypes) {
    for (const [value, count] of valueCounts) {
      for (let i = 0; i < count; i++) {
        tiles.push({ id: id++, type: t, value });
      }
    }
  }
  for (let i = 0; i < 15; i++) {
    tiles.push({ id: id++, type: "tide", value: 0 });
  }
  return shuffle(tiles);
}

function makePlayers(numBots, humanName) {
  const players = [
    { id: 0, name: humanName || "You", isBot: false, salt: 0, caramel: 0, chocolate: 0, riskTolerance: 1 },
  ];
  for (let i = 0; i < numBots; i++) {
    players.push({
      id: i + 1,
      name: BOT_NAMES[i % BOT_NAMES.length],
      isBot: true,
      salt: 0,
      caramel: 0,
      chocolate: 0,
      riskTolerance: 0.75 + Math.random() * 0.6, // 0.75 - 1.35, gives bots distinct personalities
    });
  }
  return players;
}

function initGame(numBots, humanName, startPlayerIndex) {
  const pool = createTilePool();
  const gridTiles = pool.slice(0, 25);
  const drawPile = pool.slice(25).map((t) => t.id);
  const tilesById = {};
  pool.forEach((t) => (tilesById[t.id] = t));

  const grid = gridTiles.map((t) => ({ tileId: t.id, faceUp: false }));
  const numPlayers = numBots + 1;
  const tideTokens = Array(numPlayers <= 2 ? 5 : 6).fill("white");
  const players = makePlayers(numBots, humanName);
  const startIdx = ((startPlayerIndex ?? Math.floor(Math.random() * players.length)) + players.length) % players.length;

  return {
    tilesById,
    grid,
    drawPile,
    tideTokens,
    players,
    currentPlayer: startIdx,
    startPlayerIndex: startIdx,
    revealedThisTurn: [],
    log: [
      {
        text: `${players[startIdx].name} most recently ate something sweet, so they'll go first. Good luck!`,
        kind: "info",
      },
    ],
    gameOver: false,
    finalResults: null,
    turnFlash: null, // transient banner e.g. "Rising tide!" / "High tide!"
    highTideNumber: 0,
    // A short-lived toast shown for every tide flip / high tide so it's
    // impossible to miss — auto-clears a few seconds after it's set.
    banner: null,
    // When a bot hits a rising tide or decides to stop combing, we pause here
    // (tiles stay visible face-up) until the human clicks "Continue".
    pendingBotResolution: null,
  };
}

function pushLog(state, text, kind = "info") {
  const log = [{ text, kind }, ...state.log].slice(0, 60);
  return { ...state, log };
}

function facedownIndices(state) {
  const idx = [];
  state.grid.forEach((c, i) => {
    if (c.tileId !== null && !c.faceUp) idx.push(i);
  });
  return idx;
}

function countUnknownTide(state) {
  let tide = 0;
  let total = 0;
  state.grid.forEach((c) => {
    if (c.tileId !== null && !c.faceUp) {
      total++;
      if (state.tilesById[c.tileId].type === "tide") tide++;
    }
  });
  state.drawPile.forEach((id) => {
    total++;
    if (state.tilesById[id].type === "tide") tide++;
  });
  return { tide, total };
}

function computeFinalResults(players) {
  const results = players.map((p) => {
    const caramels = Math.min(p.salt, p.caramel, p.chocolate);
    const total = p.salt + p.caramel + p.chocolate;
    const leftover = total - caramels * 3;
    const score = caramels * 5 + leftover;
    return { ...p, caramels, leftover, total, score };
  });
  // v5 tiebreaker: most caramels crafted, then most total ingredients, then share the win.
  results.sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    if (b.caramels !== a.caramels) return b.caramels - a.caramels;
    if (b.total !== a.total) return b.total - a.total;
    return 0;
  });
  return results;
}

function doHighTide(state) {
  // Gather all remaining active tiles (grid + draw pile), reshuffle, rebuild board.
  const remainingIds = [];
  state.grid.forEach((c) => {
    if (c.tileId !== null) remainingIds.push(c.tileId);
  });
  state.drawPile.forEach((id) => remainingIds.push(id));

  const shuffled = shuffle(remainingIds);
  const newGridIds = shuffled.slice(0, 25);
  const newDrawPile = shuffled.slice(25);
  const newGrid = newGridIds.map((id) => ({ tileId: id, faceUp: false }));
  // pad grid to 25 with empty cells if beach has shrunk
  while (newGrid.length < 25) newGrid.push({ tileId: null, faceUp: false });

  const newTokens = state.tideTokens.slice(0, -1).map(() => "white");

  let next = {
    ...state,
    grid: newGrid,
    drawPile: newDrawPile,
    tideTokens: newTokens,
    highTideNumber: state.highTideNumber + 1,
  };
  next = pushLog(next, `High tide! One tide token is retired, the shoreline is washed clean and reshuffled.`, "hightide");
  return next;
}

function advanceTurn(state) {
  const nextPlayer = (state.currentPlayer + 1) % state.players.length;
  return { ...state, currentPlayer: nextPlayer, revealedThisTurn: [] };
}

/** Resolve revealing a single facedown tile at `index`. Handles tide-turn-ending / high tide / game end. */
/** Return this turn's other reveals face-down, flip a tide token, handle high tide, advance turn. */
function resolveTideTurnEnd(state, playerName) {
  let next = state;

  const revealed = next.revealedThisTurn;
  if (revealed.length > 0) {
    const g2 = next.grid.slice();
    revealed.forEach((i) => {
      g2[i] = { ...g2[i], faceUp: false };
    });
    next = { ...next, grid: g2 };
  }
  next = { ...next, revealedThisTurn: [] };

  // Flip one white token to blue.
  const tideTokens = next.tideTokens.slice();
  const wIdx = tideTokens.indexOf("white");
  if (wIdx !== -1) tideTokens[wIdx] = "blue";
  next = { ...next, tideTokens };

  next = pushLog(next, `${playerName}'s turn ends empty-handed — everything returns face-down.`, "tide");

  const allBlue = next.tideTokens.every((t) => t === "blue");
  if (allBlue) {
    next = doHighTide(next);
    next = {
      ...next,
      banner: {
        id: Math.random(),
        kind: "hightide",
        title: "High tide!",
        text: `A tide token is retired (${next.tideTokens.length} left) and the whole shoreline is reshuffled.`,
      },
    };
  } else {
    next = {
      ...next,
      banner: {
        id: Math.random(),
        kind: "tide",
        title: "Rising tide!",
        text: `${playerName}'s turn ends empty-handed. One tide token flips to blue.`,
      },
    };
  }

  next = advanceTurn(next);
  return next;
}

function revealAt(state, index) {
  const cell = state.grid[index];
  if (!cell || cell.tileId === null || cell.faceUp) return state;
  const tile = state.tilesById[cell.tileId];
  const player = state.players[state.currentPlayer];

  const grid = state.grid.slice();
  grid[index] = { ...cell, faceUp: true };
  let next = { ...state, grid };

  if (tile.type === "tide") {
    // Game-end check happens BEFORE any token flip.
    if (next.tideTokens.length === 1) {
      const finalResults = computeFinalResults(next.players);
      next = pushLog(
        next,
        `${player.name} uncovers the last rising tide — the competition is over!`,
        "gameover"
      );
      return { ...next, gameOver: true, finalResults, turnFlash: "The last tide has risen. Game over!" };
    }

    next = pushLog(next, `${player.name} uncovers a rising tide!`, "tide");

    // For a bot, pause here so the human can see what was revealed before
    // it all flips back face-down — the human clicks "Continue" to resolve it.
    if (player.isBot) {
      return { ...next, pendingBotResolution: { kind: "tide" } };
    }

    // Human turns resolve immediately — they triggered this themselves.
    return resolveTideTurnEnd(next, player.name);
  }

  // Ingredient tile: just mark it revealed, turn continues.
  const revealedThisTurn = [...next.revealedThisTurn, index];
  next = { ...next, revealedThisTurn };
  next = pushLog(next, `${player.name} reveals ${TYPE_LABEL[tile.type].toLowerCase()}.`, "reveal");
  return next;
}

/** Collect all revealed tiles of `type`, return the rest face-down, refill empties, advance turn. */
/** v5 "take all but one": sacrifice exactly one revealed tile back to the tide
 *  (it stays face-down in its spot), keep every other revealed tile's chevron
 *  value on the matching stack, refill collected spots, advance the turn. */
function resolveStop(state, sacrificeIndex) {
  const player = state.players[state.currentPlayer];
  const revealed = state.revealedThisTurn;
  if (revealed.length === 0 || !revealed.includes(sacrificeIndex)) return state;

  const toCollect = revealed.filter((i) => i !== sacrificeIndex);
  const sacrificedTile = state.tilesById[state.grid[sacrificeIndex].tileId];

  // Tally gains per type before we touch the grid.
  const gains = { salt: 0, caramel: 0, chocolate: 0 };
  toCollect.forEach((i) => {
    const tile = state.tilesById[state.grid[i].tileId];
    gains[tile.type] += tile.value;
  });
  const totalGained = gains.salt + gains.caramel + gains.chocolate;

  let grid = state.grid.slice();
  grid[sacrificeIndex] = { ...grid[sacrificeIndex], faceUp: false };
  toCollect.forEach((i) => {
    grid[i] = { tileId: null, faceUp: false };
  });

  // Refill empty cells from the draw pile.
  let drawPile = state.drawPile.slice();
  grid = grid.map((c) => {
    if (c.tileId === null && drawPile.length > 0) {
      const id = drawPile.shift();
      return { tileId: id, faceUp: false };
    }
    return c;
  });

  const players = state.players.map((p, i) =>
    i === state.currentPlayer
      ? { ...p, salt: p.salt + gains.salt, caramel: p.caramel + gains.caramel, chocolate: p.chocolate + gains.chocolate }
      : p
  );

  let next = { ...state, grid, drawPile, players, revealedThisTurn: [] };
  next = pushLog(
    next,
    totalGained > 0
      ? `${player.name} stops combing, slides a ${TYPE_LABEL[sacrificedTile.type].toLowerCase()} (${sacrificedTile.value}) back to the tide, and keeps the rest — +${totalGained}.`
      : `${player.name} stops after a single flip — the tide takes it, nothing gained.`,
    "collect"
  );
  next = advanceTurn(next);
  return next;
}

/** How much value the player would net if they stopped combing right now,
 *  assuming they sacrifice the tile that hurts least (see botChooseSacrifice). */
function potentialKeepValue(state) {
  const revealed = state.revealedThisTurn;
  if (revealed.length === 0) return 0;
  const sacrificeIndex = botChooseSacrifice(state);
  let total = 0;
  revealed.forEach((i) => {
    total += state.tilesById[state.grid[i].tileId].value;
  });
  const sacrificedValue = state.tilesById[state.grid[sacrificeIndex].tileId].value;
  return total - sacrificedValue;
}

function botDecide(state) {
  const revealed = state.revealedThisTurn;
  if (revealed.length === 0) return true;

  const potential = potentialKeepValue(state);
  const { tide, total } = countUnknownTide(state);
  const fd = facedownIndices(state).length;
  if (fd === 0) return false; // nothing left to reveal

  const risk = total === 0 ? 1 : tide / total;
  const player = state.players[state.currentPlayer];
  const threshold = (1 / (potential + 1)) * (player.riskTolerance || 1);

  if (revealed.length >= 8) return false; // sanity cap
  return risk < threshold;
}

/** Pick which revealed tile to sacrifice: the one that hurts least to lose —
 *  low chevron value, and ideally a type the bot's stacks don't need. */
function botChooseSacrifice(state) {
  const player = state.players[state.currentPlayer];
  const revealed = state.revealedThisTurn;
  const minStack = Math.min(player.salt, player.caramel, player.chocolate);

  let worstIdx = revealed[0];
  let worstScore = Infinity;
  revealed.forEach((i) => {
    const tile = state.tilesById[state.grid[i].tileId];
    const isBottleneck = player[tile.type] === minStack; // this stack is the one holding back caramels
    const keepScore = tile.value + (isBottleneck ? 1.5 : 0);
    if (keepScore < worstScore) {
      worstScore = keepScore;
      worstIdx = i;
    }
  });
  return worstIdx;
}

/** Stage a bot's decision to stop combing. The human must click "Continue"
 *  to actually apply it — the revealed tiles stay visible until then. */
function stageBotStop(state, sacrificeIndex) {
  const player = state.players[state.currentPlayer];
  let next = pushLog(state, `${player.name} stops combing.`, "info");
  return { ...next, pendingBotResolution: { kind: "stop", sacrificeIndex } };
}

/** Apply whatever the bot's pending decision was (tide turn-end or stop-and-keep). */
function resolvePendingBot(state) {
  if (!state.pendingBotResolution) return state;
  const { kind, sacrificeIndex } = state.pendingBotResolution;
  const cleared = { ...state, pendingBotResolution: null };
  const player = cleared.players[cleared.currentPlayer];
  if (kind === "tide") return resolveTideTurnEnd(cleared, player.name);
  if (kind === "stop") return resolveStop(cleared, sacrificeIndex);
  return cleared;
}

function botStep(state) {
  if (state.gameOver || state.pendingBotResolution) return state;
  const player = state.players[state.currentPlayer];
  if (!player.isBot) return state;

  if (state.revealedThisTurn.length === 0) {
    const options = facedownIndices(state);
    if (options.length === 0) return state; // shouldn't happen
    const pick = options[Math.floor(Math.random() * options.length)];
    return revealAt(state, pick);
  }

  const shouldContinue = botDecide(state);
  if (shouldContinue) {
    const options = facedownIndices(state);
    if (options.length === 0) {
      return stageBotStop(state, botChooseSacrifice(state));
    }
    const pick = options[Math.floor(Math.random() * options.length)];
    return revealAt(state, pick);
  }
  return stageBotStop(state, botChooseSacrifice(state));
}

