          <div style={{ fontSize: 12, color: "#6B5A3E", marginTop: 8, display: "flex", alignItems: "center", gap: 6 }}>
            <Users size={13} /> {numBots + 1} players total &middot; {numBots + 1 <= 2 ? 5 : 6} tide tokens
          </div>
