function GameOverModal({ results, onRestart, onNewSetup }) {
  const topScore = results[0].score;
  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        background: "rgba(30,20,10,0.55)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        zIndex: 50,
        padding: 16,
      }}
    >
      <div
        className="csc-fade-in"
        style={{
          background: "#FBF4E2",
          borderRadius: 20,
          padding: 26,
          maxWidth: 480,
          width: "100%",
          border: "2px solid #D8C89B",
          maxHeight: "88vh",
          overflowY: "auto",
        }}
      >
        <div style={{ textAlign: "center", marginBottom: 16 }}>
          <Trophy size={34} color="#D9694F" style={{ marginBottom: 4 }} />
          <div className="csc-display" style={{ fontSize: 24, fontWeight: 700, color: "#8C5525" }}>
            Competition over!
          </div>
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 20 }}>
          {results.map((r, i) => (
            <div
              key={r.id}
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                background: r.score === topScore ? "#FFF1DE" : "white",
                border: `2px solid ${r.score === topScore ? "#D9694F" : "#E5DAC0"}`,
                borderRadius: 12,
                padding: "10px 14px",
              }}
            >
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <span className="csc-display" style={{ fontWeight: 600, fontSize: 15, color: "#3A2E1E", width: 18 }}>
                  {i + 1}
                </span>
                <div>
                  <div style={{ fontWeight: 700, fontSize: 14 }}>
                    {r.name} {!r.isBot && <span style={{ fontSize: 10, color: "#1F6F8B" }}>(you)</span>}
                  </div>
                  <div style={{ fontSize: 11, color: "#6B5A3E" }}>
                    {r.caramels} caramel{r.caramels === 1 ? "" : "s"} · {r.leftover} leftover
                  </div>
                </div>
              </div>
              <div className="csc-display" style={{ fontSize: 20, fontWeight: 700, color: r.score === topScore ? "#D9694F" : "#3A2E1E" }}>
                {r.score}
              </div>
            </div>
          ))}
        </div>
        <div style={{ display: "flex", gap: 10 }}>
          <button
            onClick={onRestart}
            className="csc-btn"
            style={{ flex: 1, padding: "11px 0", background: "#D9694F", color: "white" }}
          >
            Rematch
          </button>
          <button
            onClick={onNewSetup}
            className="csc-btn"
            style={{ flex: 1, padding: "11px 0", background: "white", border: "2px solid #D8C89B", color: "#3A2E1E" }}
          >
            New setup
          </button>
        </div>
      </div>
    </div>
  );
}

export default function App() {
  const [setupDone, setSetupDone] = useState(false);
  const [lastSetup, setLastSetup] = useState({ numBots: 2, humanName: "You" });
  const [state, setState] = useState(null);
  const [rulesOpen, setRulesOpen] = useState(false);
  const [selectedSacrifice, setSelectedSacrifice] = useState(null);
  const logEndRef = useRef(null);

  const startGame = useCallback((numBots, humanName, startIndex) => {
    setLastSetup({ numBots, humanName });
    setState(initGame(numBots, humanName, startIndex));
    setSetupDone(true);
  }, []);

  // Bot autoplay loop. Pauses whenever pendingBotResolution is set — the
  // human clicks "Continue" (below) to actually resolve it and move on.
  useEffect(() => {
    if (!state || state.gameOver || state.pendingBotResolution) return;
    const player = state.players[state.currentPlayer];
    if (!player || !player.isBot) return;
    const t = setTimeout(() => {
      setState((prev) => (prev ? botStep(prev) : prev));
    }, 650);
    return () => clearTimeout(t);
  }, [state]);

  // Auto-dismiss the tide/high-tide toast a few seconds after it appears.
  useEffect(() => {
    if (!state || !state.banner) return;
    const bannerId = state.banner.id;
    const t = setTimeout(() => {
      setState((prev) => (prev && prev.banner?.id === bannerId ? { ...prev, banner: null } : prev));
    }, 3800);
    return () => clearTimeout(t);
  }, [state?.banner?.id]);

  // Clear the human's sacrifice preview whenever the turn moves on or a new
  // tile gets revealed — the old choice no longer applies.
  useEffect(() => {
    setSelectedSacrifice(null);
  }, [state?.currentPlayer, state?.revealedThisTurn?.length]);

  if (!setupDone || !state) {
    return <SetupScreen onStart={startGame} />;
  }

  const currentPlayer = state.players[state.currentPlayer];
  const isHumanTurn = !currentPlayer.isBot && !state.gameOver;
  const activeTilesLeft = state.grid.filter((c) => c.tileId !== null).length + state.drawPile.length;

  // What the pending bot "stop" resolution would look like, for the banner.
  let pendingSacrificeTile = null;
  let pendingTotalGained = 0;
  if (state.pendingBotResolution?.kind === "stop") {
    const sacIdx = state.pendingBotResolution.sacrificeIndex;
    pendingSacrificeTile = state.tilesById[state.grid[sacIdx].tileId];
    state.revealedThisTurn.forEach((i) => {
      if (i !== sacIdx) pendingTotalGained += state.tilesById[state.grid[i].tileId].value;
    });
  }

  // Which grid tiles should glow green ("keeping") or orange ("returning")
  // right now — from a bot's staged decision, or the human's own preview pick.
  const highlightKeep = new Set();
  const highlightSacrifice = new Set();
  if (state.pendingBotResolution?.kind === "stop") {
    const sacIdx = state.pendingBotResolution.sacrificeIndex;
    state.revealedThisTurn.forEach((i) => (i === sacIdx ? highlightSacrifice.add(i) : highlightKeep.add(i)));
  } else if (state.pendingBotResolution?.kind === "tide") {
    state.revealedThisTurn.forEach((i) => highlightSacrifice.add(i));
  } else if (isHumanTurn && selectedSacrifice !== null && state.revealedThisTurn.includes(selectedSacrifice)) {
    state.revealedThisTurn.forEach((i) => (i === selectedSacrifice ? highlightSacrifice.add(i) : highlightKeep.add(i)));
  }

  // Summary of the human's own preview pick, for the confirm panel.
  let previewSacrificeTile = null;
  let previewTotalGained = 0;
  if (isHumanTurn && selectedSacrifice !== null && state.revealedThisTurn.includes(selectedSacrifice)) {
    previewSacrificeTile = state.tilesById[state.grid[selectedSacrifice].tileId];
    state.revealedThisTurn.forEach((i) => {
      if (i !== selectedSacrifice) previewTotalGained += state.tilesById[state.grid[i].tileId].value;
    });
  }

  return (
    <div className="csc-root">
      <GlobalStyle />
      {state.gameOver && state.finalResults && (
        <GameOverModal
          results={state.finalResults}
          onRestart={() =>
            startGame(lastSetup.numBots, lastSetup.humanName, (state.startPlayerIndex + 1) % state.players.length)
          }
          onNewSetup={() => setSetupDone(false)}
        />
      )}

      <div style={{ maxWidth: 1100, margin: "0 auto" }}>
        {/* Header */}
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16, flexWrap: "wrap", gap: 10 }}>
          <div>
            <div className="csc-display" style={{ fontSize: 24, fontWeight: 700, color: "#8C5525" }}>
              Chocolate Sea Salt Caramels
            </div>
            <div style={{ fontSize: 12, color: "#6B5A3E" }}>
              {activeTilesLeft} tiles left in play · High tide #{state.highTideNumber}
            </div>
          </div>
          <button
            onClick={() => setSetupDone(false)}
            className="csc-btn"
            style={{
              background: "white",
              border: "2px solid #D8C89B",
              color: "#3A2E1E",
              padding: "8px 14px",
              display: "flex",
              alignItems: "center",
              gap: 6,
              fontSize: 13,
            }}
          >
            <RotateCcw size={14} /> Restart
          </button>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "minmax(280px,1fr) 340px", gap: 18 }}>
          {/* LEFT: board */}
          <div>
            <div
              style={{
                background: "rgba(255,255,255,0.35)",
                border: "2px solid #D8C89B",
                borderRadius: 18,
                padding: 16,
                marginBottom: 14,
              }}
            >
              <TideBanner banner={state.banner} />
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12, flexWrap: "wrap", gap: 8 }}>
                <TideTrack tokens={state.tideTokens} />
                <div style={{ fontSize: 12, color: "#6B5A3E" }}>Draw pile: <b>{state.drawPile.length}</b></div>
              </div>

              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(5, 1fr)",
                  gridAutoRows: "1fr",
                  gap: 7,
                  maxWidth: 480,
                  margin: "0 auto",
                }}
              >
                {state.grid.map((cell, i) => {
                  const tile = cell.tileId !== null ? state.tilesById[cell.tileId] : null;
                  const selectable =
                    isHumanTurn && !state.pendingBotResolution && cell.faceUp && state.revealedThisTurn.includes(i);
                  let highlight = null;
                  if (highlightKeep.has(i)) highlight = "keep";
                  else if (highlightSacrifice.has(i)) highlight = "sacrifice";
                  return (
                    <GridTile
                      key={i}
                      cell={cell}
                      tile={tile}
                      highlight={highlight}
                      selectable={selectable}
                      disabled={!isHumanTurn || cell.faceUp}
                      onClick={() => {
                        if (cell.faceUp) {
                          if (selectable) setSelectedSacrifice((prev) => (prev === i ? null : i));
                        } else {
                          setState((prev) => revealAt(prev, i));
                        }
                      }}
                    />
                  );
                })}
              </div>
            </div>

            {/* Turn control panel */}
            <div
              style={{
                background: "#FBF4E2",
                border: "2px solid #D8C89B",
                borderRadius: 16,
                padding: 16,
                marginBottom: 14,
                minHeight: 92,
              }}
            >
              {state.gameOver ? (
                <div style={{ fontSize: 14, color: "#6B5A3E" }}>{state.turnFlash}</div>
              ) : state.pendingBotResolution ? (
                <div>
                  <div style={{ fontSize: 14, marginBottom: 10, color: "#3A2E1E" }}>
                    {state.pendingBotResolution.kind === "tide" ? (
                      <>
                        <b>{currentPlayer.name}</b> uncovered a rising tide — the turn ends empty-handed.
                        {state.revealedThisTurn.length > 0 && (
                          <> {state.revealedThisTurn.length} tile{state.revealedThisTurn.length === 1 ? "" : "s"} will flip back facedown.</>
                        )}
                      </>
                    ) : pendingTotalGained > 0 ? (
                      <>
                        <b>{currentPlayer.name}</b> stops combing, slides a{" "}
                        <b>
                          {TYPE_LABEL[pendingSacrificeTile.type].toLowerCase()} ({pendingSacrificeTile.value})
                        </b>{" "}
                        back to the tide, and keeps the rest — <b>+{pendingTotalGained}</b>.
                      </>
                    ) : (
                      <>
                        <b>{currentPlayer.name}</b> only flipped one tile and stops — the tide takes it, nothing gained.
                      </>
                    )}
                  </div>
                  <button
                    onClick={() => setState((prev) => resolvePendingBot(prev))}
                    className="csc-btn csc-pulse"
                    style={{
                      padding: "9px 20px",
                      background: "linear-gradient(160deg,#E27A5D,#C1543A)",
                      color: "white",
                      fontSize: 14,
                      boxShadow: "0 4px 12px rgba(193,84,58,0.4)",
                    }}
                  >
                    Continue →
                  </button>
                </div>
              ) : currentPlayer.isBot ? (
                <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  <div className="csc-pulse" style={{ width: 10, height: 10, borderRadius: 6, background: "#D9694F" }} />
                  <span style={{ fontSize: 14, color: "#3A2E1E" }}>
                    <b>{currentPlayer.name}</b> is combing the shoreline…
                  </span>
                </div>
              ) : (
                <div>
                  <div style={{ fontSize: 14, marginBottom: 10, color: "#3A2E1E" }}>
                    {state.revealedThisTurn.length === 0 ? (
                      "Your turn — flip a facedown tile to start combing."
                    ) : selectedSacrifice === null ? (
                      <>
                        Flip another tile, or <b>tap one of your revealed tiles above</b> to preview sending it
                        back to the tide — everything else stays.
                      </>
                    ) : previewTotalGained > 0 ? (
                      <>
                        Sending back the highlighted{" "}
                        <b>
                          {TYPE_LABEL[previewSacrificeTile.type].toLowerCase()} ({previewSacrificeTile.value})
                        </b>
                        . Everything else glowing green stays — that's <b>+{previewTotalGained}</b>. Tap a
                        different tile to change your mind, or confirm below.
                      </>
                    ) : (
                      <>You only flipped one tile — stopping now sends it right back, nothing gained.</>
                    )}
                  </div>
                  {selectedSacrifice !== null && (
                    <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                      <button
                        onClick={() => setState((prev) => resolveStop(prev, selectedSacrifice))}
                        className="csc-btn csc-pulse"
                        style={{
                          padding: "9px 20px",
                          background: "linear-gradient(160deg,#E27A5D,#C1543A)",
                          color: "white",
                          fontSize: 14,
                          boxShadow: "0 4px 12px rgba(193,84,58,0.4)",
                        }}
                      >
                        Confirm →
                      </button>
                      <button
                        onClick={() => setSelectedSacrifice(null)}
                        className="csc-btn"
                        style={{
                          padding: "9px 16px",
                          background: "white",
                          border: "2px solid #D8C89B",
                          color: "#3A2E1E",
                          fontSize: 14,
                        }}
                      >
                        Cancel
                      </button>
                    </div>
                  )}
                </div>
              )}
            </div>

            <RulesPanel open={rulesOpen} setOpen={setRulesOpen} />
          </div>

          {/* RIGHT: players + log */}
          <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {state.players.map((p, i) => (
                <PlayerCard key={p.id} player={p} isCurrent={i === state.currentPlayer && !state.gameOver} isHuman={!p.isBot} />
              ))}
            </div>

            <div
              style={{
                background: "#FBF4E2",
                border: "2px solid #D8C89B",
                borderRadius: 14,
                padding: 12,
                flex: 1,
                minHeight: 200,
                display: "flex",
                flexDirection: "column",
              }}
            >
              <div style={{ fontSize: 12, fontWeight: 700, color: "#6B5A3E", marginBottom: 6, textTransform: "uppercase", letterSpacing: 0.4 }}>
                Turn log
              </div>
              <div className="csc-scroll" style={{ overflowY: "auto", maxHeight: 320, display: "flex", flexDirection: "column", gap: 5 }}>
                {state.log.map((entry, i) => (
                  <div
                    key={i}
                    style={{
                      fontSize: 12.5,
                      lineHeight: 1.4,
                      color: entry.kind === "tide" ? "#134A5C" : entry.kind === "hightide" ? "#8C5525" : entry.kind === "gameover" ? "#D9694F" : "#3A2E1E",
                      fontWeight: entry.kind === "hightide" || entry.kind === "gameover" ? 700 : 400,
                      borderLeft: entry.kind === "tide" ? "3px solid #4FA3BD" : entry.kind === "hightide" ? "3px solid #D9694F" : "3px solid transparent",
                      paddingLeft: 7,
                    }}
                  >
                    {entry.text}
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
